--
-- Table structure for table `sys_user`
--

DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL COMMENT '用户ID（雪花ID）',
  `username` varchar(50) NOT NULL COMMENT '登录账号',
  `password` varchar(100) DEFAULT NULL COMMENT '密码',
  `nickname` varchar(50) DEFAULT NULL COMMENT '用户昵称',
  `gender` tinyint NOT NULL DEFAULT '0' COMMENT '性别[1:男，2:女，0:保密]',
  `phone` varchar(20) DEFAULT NULL COMMENT '电话',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `introduction` varchar(255) DEFAULT NULL COMMENT '用户介绍',
  `exp` int DEFAULT '0' COMMENT '用户经验值',
  `level` int DEFAULT '1' COMMENT '用户等级',
  `points` int DEFAULT '0' COMMENT '用户积分',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像地址',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态（1-正常 0-禁用）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `open_id` varchar(64) DEFAULT NULL COMMENT '小程序唯一标识符',
  `surplus_money` decimal(10,2) DEFAULT '0.00' COMMENT '用户余额',
  `birthday` date DEFAULT NULL COMMENT '生日',
  `tenant_id` bigint DEFAULT NULL COMMENT '租户ID；平台超级管理员为NULL',
  `tenant_scope_id` bigint GENERATED ALWAYS AS (ifnull(`tenant_id`,0)) STORED COMMENT '唯一约束作用域；平台为0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_username` (`tenant_scope_id`,`username`),
  UNIQUE KEY `uk_tenant_open_id` (`tenant_scope_id`,`open_id`),
  UNIQUE KEY `uk_tenant_phone` (`tenant_scope_id`,`phone`),
  UNIQUE KEY `uk_tenant_email` (`tenant_scope_id`,`email`),
  KEY `idx_tenant_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='系统用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

