DROP TABLE IF EXISTS `dish`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dish` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `dish_code` varchar(50) NOT NULL COMMENT '租户内稳定菜品编码',
  `store_id` bigint DEFAULT NULL COMMENT '迁移兼容字段；门店自建菜品所属门店，总部菜品为空',
  `source_type` tinyint NOT NULL DEFAULT '1' COMMENT '来源：0总部，1门店',
  `owner_store_id` bigint DEFAULT NULL COMMENT '门店自建菜品所属门店；总部菜品为空',
  `master_status` tinyint NOT NULL DEFAULT '1' COMMENT '总部状态：0草稿，1启用，2全局停用',
  `version` int NOT NULL DEFAULT '1' COMMENT '菜品主数据版本',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0正常，1删除',
  `category_id` bigint NOT NULL COMMENT '分类ID',
  `dish_name` varchar(100) NOT NULL COMMENT '菜品名称',
  `dish_desc` text COMMENT '菜品描述',
  `dish_pics` text COMMENT '菜品图片（JSON数组）',
  `sale_price` decimal(10,2) NOT NULL COMMENT '总部正常售价；活动与会员价由定价中心计算',
  `cost_price` decimal(10,2) DEFAULT NULL COMMENT '成本价',
  `unit` varchar(10) DEFAULT '份' COMMENT '单位',
  `stock` int NOT NULL DEFAULT '999' COMMENT '库存数量',
  `sales_count` int NOT NULL DEFAULT '0' COMMENT '销量',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览量',
  `is_recommend` tinyint NOT NULL DEFAULT '0' COMMENT '是否推荐：0-否，1-是',
  `is_hot` tinyint NOT NULL DEFAULT '0' COMMENT '是否热门：0-否，1-是',
  `is_new` tinyint NOT NULL DEFAULT '0' COMMENT '是否新品：0-否，1-是',
  `scene_type` tinyint NOT NULL DEFAULT '3' COMMENT '适用场景：0-堂食，1-外卖，2-通用',
  `sale_status` tinyint NOT NULL DEFAULT '1' COMMENT '销售状态：0-下架，1-上架',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序值，数字越小越靠前',
  `tags` varchar(255) DEFAULT NULL COMMENT '商品标签（JSON数组）',
  `allergens` varchar(255) DEFAULT NULL COMMENT '过敏原信息',
  `nutrition_info` text COMMENT '营养信息（JSON）',
  `cooking_time` int DEFAULT '0' COMMENT '制作时间（分钟）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_dish_code` (`tenant_id`,`dish_code`),
  KEY `idx_tenant_store_category_status` (`tenant_id`,`store_id`,`category_id`,`sale_status`),
  KEY `idx_tenant_store_status_sort` (`tenant_id`,`store_id`,`sale_status`,`sort_order`),
  KEY `idx_tenant_source_owner` (`tenant_id`,`source_type`,`owner_store_id`,`deleted`),
  KEY `idx_tenant_master_status` (`tenant_id`,`master_status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='菜品表';
/*!40101 SET character_set_client = @saved_cs_client */;

