--
-- Table structure for table `restaurant_order_item`
--

DROP TABLE IF EXISTS `restaurant_order_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `restaurant_order_item` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `order_id` bigint NOT NULL COMMENT '订单ID',
  `dish_id` bigint NOT NULL COMMENT '菜品ID',
  `category_id` bigint DEFAULT NULL COMMENT '下单时菜品分类ID',
  `unit_list_price` decimal(10,2) NOT NULL COMMENT '门店正常售价快照（含规格）',
  `unit_selling_price` decimal(10,2) NOT NULL COMMENT '会员/活动后的成交单价',
  `unit_cost_snapshot` decimal(10,2) DEFAULT NULL COMMENT '下单时门店实际单位成本快照；为空表示未维护成本',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '数量',
  `discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '订单项全部优惠金额',
  `line_payable_amount` decimal(10,2) NOT NULL COMMENT '订单项最终应付金额',
  `line_cost_amount` decimal(12,2) DEFAULT NULL COMMENT '当前剩余数量对应的成交成本总额',
  `is_gift` tinyint DEFAULT '0' COMMENT '是否赠送（0-否，1-是）',
  `spec_options_text` varchar(255) DEFAULT NULL COMMENT '选择的规格',
  `note` varchar(255) DEFAULT NULL COMMENT '备注（口味要求等）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `batch_no` int DEFAULT '1' COMMENT '批次号(第几次下单，1表示首次，2表示第二次加菜)',
  `add_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '加菜时间',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `idx_tenant_order_batch` (`tenant_id`,`order_id`,`batch_no`),
  KEY `idx_tenant_dish_gift` (`tenant_id`,`dish_id`,`is_gift`),
  KEY `idx_tenant_category_gift` (`tenant_id`,`category_id`,`is_gift`),
  KEY `idx_tenant_order_dish` (`tenant_id`,`order_id`,`dish_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单商品表';
/*!40101 SET character_set_client = @saved_cs_client */;

